// KYC Verification Pipeline: core logic (ported from main.py)

// ---- input normaliser (works for Webhook, Form, WhatsApp, Gmail, Sheets and sample data)
const input = $input.all().flatMap(i => {
  const j = i.json || {};
  if (j.messages && Array.isArray(j.messages)) {           // WhatsApp Trigger
    return j.messages.filter(m => m.text).map(m => ({ from: '+' + m.from, text: m.text.body }));
  }
  if (j.Subject !== undefined || j.From !== undefined) {     // Gmail Trigger (simple)
    return [{ from: (j.From || '').replace(/.*<|>.*/g, ''), subject: j.Subject || '', body: j.snippet || j.text || '' }];
  }
  const b = (j.body !== undefined && j.headers !== undefined) ? j.body : j;   // Webhook wraps payload in body
  if (Array.isArray(b)) return b;
  if (b && Array.isArray(b.items)) return b.items;
  return [b];
});

const KEYWORDS = { national_id: ['national identification', 'nin', 'national identity'], passport: ['passport', 'nationality'],
                   drivers_licence: ['driver', 'licence', 'license no'], utility_bill: ['electricity', 'meter', 'bill', 'disco'] };
const ACCEPTED = ['national_id', 'passport', 'drivers_licence'];
const today = new Date().toISOString().slice(0, 10);
const classify = t => { t = t.toLowerCase(); let best = 'unknown', bs = 0;
  for (const [k, ws] of Object.entries(KEYWORDS)) { const s = ws.filter(w => t.includes(w)).length; if (s > bs) { bs = s; best = k; } } return best; };
const field = (t, label) => { const m = t.match(new RegExp(label + '\\s*:\\s*(.+)', 'i')); return m ? m[1].trim() : null; };
const words = s => (s || '').toLowerCase().replace(/[^a-z ]/g, '').split(/\s+/).filter(Boolean).sort();
const sim = (a, b) => { const A = words(a), B = words(b); const inter = A.filter(w => B.includes(w)).length;
  return (2 * inter) / (A.length + B.length || 1); };
const out = [];
for (const s of input) {
  const doc = s.document_text || '', form = s.form || {}, checks = {};
  const kind = classify(doc); checks.document_type = kind;
  let status, reason;
  if (!ACCEPTED.includes(kind)) { status = 'REJECTED'; reason = `We received a ${kind.replace('_', ' ')}. Please upload a national ID, passport or driver's licence.`; }
  else {
    const name = field(doc, 'name'), dob = field(doc, 'date of birth'), exp = field(doc, 'expiry');
    const ns = sim(name, form.full_name); Object.assign(checks, { name_on_id: name, name_similarity: ns, dob_on_id: dob, expiry: exp });
    if (exp && exp < (s.today || today)) { status = 'REJECTED'; reason = `Your ID expired on ${exp}. Please upload a valid, unexpired ID.`; }
    else if (dob !== form.date_of_birth) { status = 'REFERRED'; reason = 'date_of_birth differs between ID and form'; }
    else if (ns < 0.5) { status = 'REJECTED'; reason = "The name on your ID doesn't match your signup name."; }
    else if (ns < 0.99 || (s.face_match_score != null && s.face_match_score < 0.8)) { status = 'REFERRED'; reason = ns < 0.99 ? 'name partially matches' : 'low face-match score'; }
    else { status = 'VERIFIED'; reason = 'all checks passed'; }
  }
  out.push({ route: status, customer_id: s.customer_id, status, reason, checks: JSON.stringify(checks) });
}
return out.map(json => ({ json }));
